"""Generate all wire types from the canonical versioned JSON Schema registry."""

import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
schemas = json.loads((root / "packages/contracts/schema.json").read_text())["$defs"]
ts = ["// GENERATED by scripts/generate-contracts.py. Do not edit."]
py = [
    "# GENERATED from canonical JSON Schema. Do not edit.",
    "from typing import Annotated, Literal",
    "from pydantic import BaseModel, ConfigDict, Field",
    'DecimalString = Annotated[str, Field(pattern=r"^-?(?:0|[1-9]\\d{0,15})(?:\\.\\d{1,8})?$")]',
]
rs = [
    "// GENERATED. Decimal strings are never converted to floats.",
    "use serde::{Serialize, Deserialize};",
    "pub mod api;",
]
for name, schema in schemas.items():
    ts.append(f"export type {name} = {{")
    py.extend(
        [f"class {name}(BaseModel):", '    model_config = ConfigDict(extra="forbid")']
    )
    fields = []
    for key, p in schema["properties"].items():
        vals = p.get("enum", [p["const"]] if "const" in p else None)
        typ = p.get("type", "string")
        required = key in schema.get("required", [])
        tt = (
            " | ".join(json.dumps(x) for x in vals)
            if vals
            else {
                "string": "string",
                "integer": "number",
                "number": "number",
                "boolean": "boolean",
            }[typ]
        )
        ts.append(f"  {key}{'' if required else '?'}: {tt};")
        pt = (
            "Literal[" + ", ".join(repr(x) for x in vals) + "]"
            if vals
            else {
                "string": "str",
                "integer": "int",
                "number": "float",
                "boolean": "bool",
            }[typ]
        )
        if p.get("pattern"):
            pt = f"Annotated[str, Field(pattern={p['pattern']!r})]"
        py.append(
            f"    {key}: {pt}" + (f" = {p['default']!r}" if "default" in p else "")
        )
        rt = {"string": "String", "integer": "i64", "number": "f64", "boolean": "bool"}[
            typ
        ]
        if vals:
            en = name + "".join(x.title() for x in key.split("_"))
            rs.extend(
                ["#[derive(Debug, Clone, Serialize, Deserialize)]", f"pub enum {en} {{"]
            )
            for i, v in enumerate(vals):
                rs.append(f"    #[serde(rename = {json.dumps(v)})] V{i},")
            rs.append("}")
            rt = en
        if not required:
            rt = f"Option<{rt}>"
        fields.append(f"    pub {key}: {rt},")
    ts.append("};")
    rs.extend(
        [
            "#[derive(Debug, Clone, Serialize, Deserialize)]",
            "#[serde(deny_unknown_fields)]",
            f"pub struct {name} {{",
            *fields,
            "}",
        ]
    )
    py.append("")
(root / "packages/contracts/generated.ts").write_text("\n".join(ts) + "\n")
(root / "apps/web/src/generated.ts").write_text("\n".join(ts) + "\n")
(root / "packages/contracts/generated.py").write_text("\n".join(py) + "\n")
(root / "services/api/app/contracts_generated.py").write_text("\n".join(py) + "\n")
folder = root / "packages/contracts/rust/src"
folder.mkdir(parents=True, exist_ok=True)
(folder / "lib.rs").write_text("\n".join(rs) + "\n")
print(f"Generated {len(schemas)} Python, TypeScript and Rust contracts.")
